import { readyApi } from './api.js';
import { livePrefixState, verifierMatches, workbookRecallCue, workbookSlotCh } from './workbook-assistance.js?v=workbook-answer-action-2';
import { createReaderInlineGloss, readerSentenceMarkup } from './reader-inline-gloss.js?v=inline-reader-2';
import { gradeLocalWorkbook, gradeWorkbookCorrectionPairs, revealLocalWorkbook } from './deterministic-grading.js?v=workbook-local-first-1';
import { reviewExportDocumentHtml } from './review-export.js?v=review-pdf-1';
import { workbookWritingHtml, renderWritingPrefixState } from './workbook-writing-ui.js?v=studio-preview-1';
import { workbookProgressPercent, workbookProgressVisual } from './workbook-progress.js?v=infinite-progress-1';

const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const SESSION_KEY='ready-student-session';
const CACHE_INDEX='ready-passage-cache-v2:';
const DASHBOARD_CACHE='ready-dashboard-cache-v1:';
const WORKBOOK_CACHE='ready-workbook-cache-v1:';
const WORKBOOK_ATTEMPTS='ready-workbook-attempt-queue-v1:';
const state={token:'',student:null,scope:null,passages:[],resume:null,passage:null,sentences:[],savedWords:[],workbookSession:null,reviewData:null,reviewExportData:null,reviewKind:'word',reviewCount:0};
let busyCount=0,toastTimer,readerGlossController=null,workbookFlushTimer=null,workbookAttemptQueue=[];

function busy(on,label='잠시만요…'){busyCount=Math.max(0,busyCount+(on?1:-1));$('#busy').hidden=!busyCount;$('#busy span:last-child').textContent=label;}
function toast(message,ms=1900){const node=$('#toast');node.textContent=message;node.classList.add('on');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('on'),ms);}
function theme(next){const dark=next==='dark';document.documentElement.classList.toggle('dark',dark);document.body.classList.toggle('dark',dark);localStorage.setItem('ready-theme',next);}
async function call(op,data={},token=state.token,label='잠시만요…'){busy(true,label);try{return await readyApi(op,data,token);}finally{busy(false);}}
function record(op,data={}){readyApi(op,data,state.token).catch(()=>{});}
function dashboardCacheKey(){return `${DASHBOARD_CACHE}${state.token.slice(-12)}`;}
function clearSession(){if(state.token)localStorage.removeItem(dashboardCacheKey());localStorage.removeItem(SESSION_KEY);Object.assign(state,{token:'',student:null,scope:null,passages:[],passage:null,sentences:[],savedWords:[],workbookSession:null,reviewData:null,reviewExportData:null,reviewKind:'word',reviewCount:0});}
async function safely(job,{auth=true}={}){try{return await job();}catch(error){if(auth&&error.status===401){clearSession();showStudentLogin();}toast(error.message||'요청을 처리하지 못했습니다.',3600);return null;}}
function show(...ids){if(!ids.some(id=>['student-reader','student-workbook'].includes(id))&&readerGlossController){readerGlossController.destroy();readerGlossController=null;}['student-home','student-sets','student-review','student-reader','student-workbook','student-library'].forEach(id=>$('#'+id).hidden=!ids.includes(id));document.body.classList.toggle('study-mode',ids.includes('student-reader')||ids.includes('student-workbook'));}
function updateStudentNav(){const nav=$('#student-nav');nav.hidden=!state.token;$('#logout').hidden=!state.token;const review=nav.querySelector('[data-student-route="review"]');if(review)review.innerHTML=`Review${state.reviewCount?` <span>${state.reviewCount}</span>`:''}`;}

function showStudentLogin(){show('student-home');updateStudentNav();requestAnimationFrame(()=>$('#student-code')?.focus());}
async function login(form){const values=Object.fromEntries(new FormData(form)),data=await safely(()=>call('student_login',{code:values.code,remember:true},'','학생 코드를 확인하는 중…'),{auth:false});form.reset();$('#student-code').blur();if(!data)return;state.token=data.session.token;state.student=data.student;localStorage.setItem(SESSION_KEY,JSON.stringify(data.session));await loadDashboard();}
function applyDashboard(data){state.student=data.student;state.scope=data.scope;state.passages=data.passages||[];state.resume=data.resume||null;state.savedWords=data.savedWords||[];state.reviewCount=Number(data.reviewCount)||0;updateStudentNav();renderScope();}
async function loadDashboard(){let cached=null;try{cached=JSON.parse(localStorage.getItem(dashboardCacheKey())||'null');}catch{}if(cached?.student&&state.token)applyDashboard(cached);const data=await safely(()=>(cached?readyApi('student_bootstrap_active',{},state.token):call('student_bootstrap_active',{},state.token,'학습 범위를 준비하는 중…')));if(!data)return;applyDashboard(data);try{localStorage.setItem(dashboardCacheKey(),JSON.stringify(data));}catch{}prefetchWorkbooks();restoreWorkbookAttempts();flushWorkbookAttempts();}

function hasWorkbook(passage){return passage?.has_workbook===true;}
function passageChoice(passage,index){const workbook=hasWorkbook(passage),kind=passage.source_type==='TEXTBOOK'?'교과서 본문':'모의고사';return `<article class="passage-row"><button class="passage-open" type="button" data-start-passage="${passage.id}"><span class="passage-index">${String(index+1).padStart(2,'0')}</span><span class="passage-copy"><strong>${esc(passage.title)}</strong><small>${kind} · ${workbook?'Workbook 학습 가능':'지문 읽기'}</small></span><b aria-hidden="true">›</b></button>${workbook?`<div class="passage-actions"><button class="passage-workbook" type="button" data-start-workbook="${passage.id}">시작하기</button></div>`:''}</article>`;}
function scopePassagesHtml(){const blocks=[];for(let index=0;index<state.passages.length;){const passage=state.passages[index];if(!passage.groupKey){blocks.push(`<div class="passage-list">${passageChoice(passage,index)}</div>`);index+=1;continue;}const start=index,group=[];while(index<state.passages.length&&state.passages[index].groupKey===passage.groupKey){group.push(state.passages[index]);index+=1;}blocks.push(`<details class="student-scope-group" open><summary><strong>${esc(passage.groupLabel)}</strong><span><small>${group.length}지문</small><b aria-hidden="true">⌄</b></span></summary><div class="passage-list">${group.map((item,offset)=>passageChoice(item,start+offset)).join('')}</div></details>`);}return `<div class="scope-passage-layout">${blocks.join('')}</div>`;}
function renderScope(){state.workbookSession=null;show('student-sets');const content=!state.scope?'<div class="empty scope-empty"><strong>아직 배정된 시험범위가 없습니다.</strong></div>':state.passages.length?scopePassagesHtml():'<div class="empty scope-empty"><strong>아직 배정된 지문이 없습니다.</strong></div>',resume=state.resume?`<section class="student-resume"><div><p class="eyebrow">RESUME</p><strong>${esc(state.resume.passageTitle)}</strong><span>${state.resume.stage?'Workbook 이어서 학습':'이어서 학습하기'}</span></div><button class="button primary" type="button" data-start-workbook="${esc(state.resume.passageId)}">이어서 하기</button></section>`:'';$('#student-sets').innerHTML=`${resume}<div class="home-head"><span>학습할 지문</span><small>${state.scope?`${esc(state.student.school)} · ${esc(state.student.grade)} · ${state.passages.length}개`:''}</small></div><div class="home-content">${content}</div>`;}

function workbookCurrent(){const session=state.workbookSession,stage=session?.data.stages[session.stageIndex];return {session,stage,item:stage?.items[session.itemIndex]};}
function workbookStageLabel(stage){return String(stage?.title||stage?.instruction||'Workbook').replace(/^\s*\d+\s*단계\s*[·:—-]?\s*/,'')||'Workbook';}
function workbookValues(session,item){return session.responses[item.key]||Array(item.slotCount).fill('');}
function workbookSlotState(result,index){return result?(result.slotResults?.[index]?'correct':'wrong'):'';}
function workbookAssistanceState(session,item){session.assistance??={};return session.assistance[item.key]??={hintCount:0,usedFullAnswerHint:false,hintReceipt:'',hints:{},live:{},requestSequence:{}};}
function ensureWorkbookAssistance(session,item){return !item?.assistance?.mode||Array.isArray(item.assistance.slots);}
function workbookBlankHtml(item,values,result,session,lookupText=null){const assistance=workbookAssistanceState(session,item),recall=item.assistance?.mode==='recall_unlock',live=item.assistance?.mode==='prefix_typing';let slot=0;return String(item.prompt||'').split(/_{5,}/).map((part,index,all)=>{const copy=lookupText&&/[A-Za-z]/.test(part)?lookupText(part,`prompt:${index}`):esc(part);if(index===all.length-1)return copy;const value=values[slot]||'',expected=result?.answers?.[slot]||'',status=workbookSlotState(result,slot),hint=item.hints?.[slot],measure=[value,hint,expected,'답'].reduce((longest,candidate)=>workbookSlotCh(candidate)>workbookSlotCh(longest)?candidate:longest,''),slotCh=workbookSlotCh(measure),liveState=assistance.live?.[slot],input=`<span class="workbook-blank ${status}${recall?' recall-slot':''}${live&&liveState?.valid===false?' live-mismatch':''}${slotCh>24?' long-slot':''}" style="--workbook-slot-ch:${slotCh}"><input type="text" data-workbook-slot="${slot}" ${recall?`data-workbook-recall="${esc(item.assistance.recallMode)}"`:''} ${live?'data-workbook-live-prefix="true"':''} value="${esc(value)}" placeholder="${esc(hint||'')}" aria-label="빈칸 ${slot+1}${hint?` (${esc(hint)})`:''}" ${result?'disabled':''} autocomplete="off" autocapitalize="off" spellcheck="false">${live&&liveState?.valid===false?`<small class="workbook-live-copy"><span>${esc(value.slice(0,liveState.mismatchIndex))}</span><b>${esc(value.slice(liveState.mismatchIndex))}</b></small>`:''}${assistance.hints?.[slot]?`<small class="workbook-slot-hint">힌트: ${esc(assistance.hints[slot])}</small>`:''}${result&&status==='wrong'?`<small class="workbook-answer">정답: ${esc(expected)}</small>`:''}</span>`;slot+=1;return copy+input;}).join('');}
function workbookChoiceHtml(item,values,result,lookupText=null){let partIndex=0;return String(item.prompt||'').split(/(⟦CHOICE:\d+⟧)/).map(part=>{const marker=part.match(/^⟦CHOICE:(\d+)⟧$/);if(!marker){const index=partIndex++;return lookupText&&/[A-Za-z]/.test(part)?lookupText(part,`prompt:${index}`):esc(part);}const index=Number(marker[1]),status=workbookSlotState(result,index),options=item.groups?.[index]||[];return `<span class="workbook-choice-group ${status}" role="group" aria-label="둘 중 하나 선택 ${index+1}">${options.map((option,optionIndex)=>`<button type="button" data-workbook-choice-group="${index}" data-workbook-choice-value="${esc(option)}" class="workbook-choice${values[index]===option?' selected':''}" aria-pressed="${values[index]===option}" ${result?'disabled':''}><span>${esc(option)}</span>${values[index]===option?'<b aria-hidden="true">✓</b>':''}</button>${optionIndex===0?'<i class="workbook-choice-or" aria-hidden="true">또는</i>':''}`).join('')}${result&&status==='wrong'?`<small>정답: ${esc(result.answers[index])}</small>`:''}</span>`;}).join('');}
function workbookCorrectionHtml(item,values,result,lookupText=null){const prompt=lookupText&&/[A-Za-z]/.test(item.prompt)?lookupText(item.prompt,'prompt:0'):esc(item.prompt),type=item.subtype==='grammar'?'어법':item.subtype==='context'?'문맥':'표현',instruction=item.subtype==='grammar'?'어법상 어색한 표현을 찾아 바르게 고치세요.':item.subtype==='context'?'문맥상 어색한 표현을 찾아 바르게 고치세요.':'어색한 표현을 찾아 바르게 고치세요.';return `<p class="workbook-correction-instruction"><strong>${type}</strong><span>${instruction}</span></p><div class="workbook-task-passage" lang="en">${prompt}</div><div class="workbook-correction-list">${Array.from({length:item.pairCount},(_,pair)=>{const wrongIndex=pair*2,correctIndex=wrongIndex+1,status=result?(result.slotResults?.[wrongIndex]&&result.slotResults?.[correctIndex]?'correct':'wrong'):'';return `<div class="workbook-correction-row ${status}"><span>${pair+1}</span><label>어색한 표현<input type="text" data-workbook-slot="${wrongIndex}" value="${esc(values[wrongIndex]||'')}" ${result?'disabled':''} autocomplete="off" autocapitalize="off" spellcheck="false"></label><b aria-hidden="true">→</b><label>바르게 고치기<input type="text" data-workbook-slot="${correctIndex}" value="${esc(values[correctIndex]||'')}" ${result?'disabled':''} autocomplete="off" autocapitalize="off" spellcheck="false"></label>${result&&status==='wrong'&&result.answers?.length?`<small>${esc(result.answers[wrongIndex])} → ${esc(result.answers[correctIndex])}</small>`:''}</div>`;}).join('')}</div>`;}
function workbookOrderSelections(session,item){session.orderSelections??={};return session.orderSelections[item.key]??=Array.from({length:item.groups?.length||0},()=>[]);}
function workbookOrderGroupHtml(item,index,result,session){const selections=workbookOrderSelections(session,item),group=item.groups?.[index]||[],chosen=selections[index]||[],chosenSet=new Set(chosen),status=workbookSlotState(result,index);return `<span class="workbook-order-group ${status}" data-workbook-order-group="${index}"><span class="workbook-order-built" aria-label="배열한 문장">${chosen.length?chosen.map(chipIndex=>`<button type="button" data-workbook-order-remove="${index}:${chipIndex}" ${result?'disabled':''}>${esc(group[chipIndex])}</button>`).join(' '):''}</span><span class="workbook-order-bank" aria-label="선택할 단어">${group.map((word,chipIndex)=>`<span class="workbook-order-bank-slot ${chosenSet.has(chipIndex)?'used':''}"><button type="button" data-workbook-order-add="${index}:${chipIndex}" ${chosenSet.has(chipIndex)?'aria-hidden="true" tabindex="-1"':''} ${result?'disabled':''}>${esc(word)}</button></span>`).join('')}</span>${result&&status==='wrong'?`<small>정답: ${esc(result.answers[index])}</small>`:''}</span>`;}
function workbookOrderHtml(item,values,result,session,lookupText=null){let partIndex=0;return String(item.prompt||'').split(/(⟦ORDER:\d+⟧)/).map(part=>{const marker=part.match(/^⟦ORDER:(\d+)⟧$/);if(marker)return workbookOrderGroupHtml(item,Number(marker[1]),result,session);const index=partIndex++;return lookupText&&/[A-Za-z]/.test(part)?lookupText(part,`prompt:${index}`):esc(part);}).join('');}
function stabilizeWorkbookOrderGeometry(root=document){const groups=root.matches?.('.workbook-order-group')?[root]:[...(root.querySelectorAll?.('.workbook-order-group')||[])];groups.forEach(group=>{const bank=group.querySelector('.workbook-order-bank'),built=group.querySelector('.workbook-order-built');if(bank&&built){const style=getComputedStyle(built),chrome=Number.parseFloat(style.paddingTop)+Number.parseFloat(style.paddingBottom)+Number.parseFloat(style.borderTopWidth)+Number.parseFloat(style.borderBottomWidth);group.style.setProperty('--workbook-order-stable-height',`${Math.ceil(bank.getBoundingClientRect().height+chrome)}px`);}});}
function refreshWorkbookOrderGroup(index){const {session,item}=workbookCurrent(),current=document.querySelector(`[data-workbook-order-group="${index}"]`);if(!session||!item||!current)return renderWorkbook();const template=document.createElement('template');template.innerHTML=workbookOrderGroupHtml(item,index,session.results[item.key],session).trim();const next=template.content.firstElementChild,stableHeight=current.style.getPropertyValue('--workbook-order-stable-height');if(stableHeight)next.style.setProperty('--workbook-order-stable-height',stableHeight);current.replaceWith(next);stabilizeWorkbookOrderGeometry(next);}
function workbookTaskHtml(item,values,result,session,lookupText=null){if(item.kind==='translation_ai'||item.kind==='translation_input')return `<label class="workbook-translation"><span>나의 해석</span><textarea rows="3" data-workbook-slot="0" ${result?'disabled':''} placeholder="우리말 해석을 입력하세요">${esc(values[0]||'')}</textarea></label>`;if(item.kind==='full_sentence_input'){const assistance=workbookAssistanceState(session,item);return workbookWritingHtml({value:values[0]||'',disabled:!!result,visibleAnswer:assistance.visibleAnswer||'',liveState:assistance.live?.[0]});}if(item.kind==='choice_groups')return `<div class="workbook-prompt choice-task" lang="en">${workbookChoiceHtml(item,values,result,lookupText)}</div>`;if(item.kind==='correction_pairs')return workbookCorrectionHtml(item,values,result,lookupText);if(item.kind==='reorder_groups')return `<div class="workbook-prompt order-task" lang="en">${workbookOrderHtml(item,values,result,session,lookupText)}</div>`;return `<div class="workbook-prompt" lang="${item.semanticType==='korean_blank'?'ko':'en'}">${workbookBlankHtml(item,values,result,session,lookupText)}</div>`;}
function workbookTabsHtml(session){return session.data.stages.map((stage,index)=>{const progress=workbookProgressVisual(stage.progressPercent);return `<button type="button" data-workbook-stage="${index}" class="${index===session.stageIndex?'active':''}" ${stage.locked?'disabled aria-disabled="true"':''}><span>${esc(workbookStageLabel(stage))}${stage.locked?' · 준비 중':''}</span><b>${stage.locked?'잠김':`${progress.percent}%`}</b></button>`;}).join('');}
function workbookStageChoicesHtml(session){return session.data.stages.map((stage,index)=>{const available=!stage.locked&&stage.items.length,label=workbookStageLabel(stage),progress=workbookProgressVisual(stage.progressPercent);return `<button class="workbook-stage-option progress-cycle-${progress.cycle}" type="button" data-workbook-stage="${index}" ${available?'':`disabled aria-disabled="true"`} style="--workbook-progress:${progress.fill}%"><span class="workbook-stage-copy"><strong>${esc(label)}</strong><span class="workbook-stage-gauge" aria-hidden="true"><i></i></span></span><span class="workbook-stage-state"><small>${available?`${progress.percent}%`:'준비 중'}</small><b aria-hidden="true">${available?'→':'—'}</b></span></button>`;}).join('');}
function renderWorkbookStages(){const session=state.workbookSession;if(!session)return renderScope();show('student-workbook');document.body.classList.remove('study-mode');$('#student-workbook').innerHTML=`<div class="workbook-stage-picker"><header class="filter-head workbook-picker-head"><button class="back-link" type="button" data-exit-workbook>← Home</button><p class="eyebrow">READY · WORKBOOK</p><h1>${esc(session.data.title)}</h1><p>학습할 항목을 선택하세요. 이어서 풀 항목에는 현재 진도가 표시됩니다.</p></header><section class="workbook-stage-list" aria-labelledby="workbook-stage-title"><div class="workbook-stage-list-head"><h2 id="workbook-stage-title">학습 선택</h2><small>${session.data.stages.filter(stage=>!stage.locked&&stage.items.length).length}개</small></div>${workbookStageChoicesHtml(session)}</section></div>`;}
function workbookFeedbackHtml(item,result){if(!result)return'';const translation=item.kind==='translation_ai'||item.semanticType==='translation';if(result.revealedAnswer){const answer=translation&&result.answers?.[0]?`<span class="workbook-revealed-answer">${esc(result.answers[0])}</span>`:'';return `<div class="workbook-feedback wrong"><strong>정답을 확인했습니다.</strong><span class="workbook-feedback-copy">${answer}<span>이번 문제는 Review에 자동 저장했습니다.</span></span></div>`;}if(translation&&(Number.isFinite(result.aiScore)||result.aiFeedback)){const lines=(result.aiFeedbackLines?.length?result.aiFeedbackLines:[result.aiFeedback]).filter(Boolean).slice(0,3);return `<div class="workbook-feedback ${result.correct?'correct':'wrong'}"><strong>${Number.isFinite(result.aiScore)?`${result.aiScore}점 · `:''}${result.correct?'통과':'다시 해보기'}</strong><span class="workbook-feedback-copy">${lines.map(line=>`<span>${esc(line)}</span>`).join('')}</span></div>`;}if(result.completedAfterHint)return `<div class="workbook-feedback wrong"><strong>끝까지 완성했습니다.</strong><span>전체 답 힌트를 사용해 이번 기록은 복습에 추가됐어요. 다음에는 힌트 없이 다시 풀어 보세요.</span></div>`;return `<div class="workbook-feedback ${result.correct?'correct':'wrong'}"><strong>${result.correct?'정답입니다.':'표시된 부분만 고쳐 보세요.'}</strong><span>${esc(result.aiFeedback||(result.correct?'Enter를 누르거나 다음 문장으로 넘어가세요.':'Review에 자동 저장했습니다. 맞은 부분은 유지됩니다.'))}</span></div>`;}
function workbookResponseReady(session,item){if(item.kind==='reorder_groups'){const selections=workbookOrderSelections(session,item);return (item.groups||[]).length===item.slotCount&&(item.groups||[]).every((group,index)=>(selections[index]||[]).length===group.length);}const values=workbookValues(session,item);return values.length===item.slotCount&&values.every(value=>String(value).trim());}
function workbookResultActionHtml(result,nextLabel){if(!result)return'';return `<div class="workbook-actions">${!result.correct?'<button class="button primary" type="button" data-workbook-retry>지금 재시도</button><button class="button quiet" type="button" data-workbook-later>나중에 다시하기</button>':`<button class="button primary" type="button" data-workbook-next>${nextLabel}</button>`}</div>`;}
function workbookToolbarActionHtml(item,result){if(result)return'';return item.semanticType==='writing'?'<button class="workbook-answer-action" type="button" data-workbook-hint>힌트 보기</button>':'';}
function workbookSubmitHtml(session,item,result){if(result)return'';return `<div class="workbook-submit-actions"><button class="button primary" type="button" data-submit-workbook>제출</button></div>`;}
function workbookAiStatusHtml(session,item){if(session.aiPending?.[item.key])return '<div class="local-ai-status" role="status"><strong>AI가 해석을 확인하고 있어요…</strong><span>작성한 답안은 그대로 유지됩니다.</span></div>';const error=session.aiErrors?.[item.key];return error?`<div class="local-ai-status error" role="status"><strong>${esc(error)}</strong><span>연결을 확인한 뒤 다시 채점해 주세요.</span></div>`:'';}
function bookmarkIcon(active=false){return `<span class="bookmark-star" aria-hidden="true">${active?'★':'☆'}</span>`;}
