  readerGlossController?.destroy();readerGlossController=null;
  if(!readerGlossEnabled()){const structured=structuredReaderBody(false),units=readerUnits(),lead=structured?'':units.shift()||'',paragraphs=structured?[]:readerParagraphs(units);show('student-reader');$('#student-reader').innerHTML=`<button class="study-back" type="button" data-exit-study aria-label="학습 목록으로"><span aria-hidden="true">‹</span></button><div class="reader-shell reader-document"><p class="eyebrow">PASSAGE</p><h1>${esc(state.passage.title)}</h1>${lead?`<p class="reader-lede">${esc(lead)}</p>`:''}<article class="reader-prose">${structured|| (paragraphs.length?paragraphs.map(paragraph=>`<p>${esc(paragraph)}</p>`).join(''):`<p>${plainPassage()}</p>`)}</article>${readerWorkbookAction()}</div>`;return;}
  const lookupSentences=state.sentences.filter(sentence=>(sentence.block_type||'SENTENCE')==='SENTENCE').map(sentence=>({id:sentence.id,text:String(sentence.text||'').trim(),translation:String(sentence.translation||'')})).filter(sentence=>sentence.text),structured=structuredReaderBody(true),sentences=[...lookupSentences],lead=structured?'':sentences.shift(),paragraphs=structured?[]:readerGlossParagraphs(sentences),root=$('#student-reader');show('student-reader');root.dataset.readerPassageId=state.passage.id;root.innerHTML=`<button class="study-back" type="button" data-exit-study aria-label="학습 목록으로"><span aria-hidden="true">‹</span></button><div class="reader-shell reader-document"><p class="eyebrow">PASSAGE</p><h1>${esc(state.passage.title)}</h1>${lead?`<p class="reader-lede">${readerGlossSentenceHtml(lead)}</p>`:''}<article class="reader-prose">${structured||(paragraphs.length?paragraphs.map(paragraph=>`<p>${paragraph.map(readerGlossSentenceHtml).join(' ')}</p>`).join(''):'<p></p>')}</article>${readerWorkbookAction()}<p class="reader-inline-notice" data-reader-gloss-notice hidden></p><span class="sr-only" data-reader-gloss-live aria-live="polite"></span></div>`;
  attachWordLookup(root,state.passage,lookupSentences);
